"""Questions and stability chapters. All plots are original calculations, not source figures."""
from html import escape
from math import sqrt, hypot, atan2, sin, cos, pi
from visual_aids import Drawing, figure

def eq(s):return '<div class="eq">\\['+escape(s)+'\\]</div>'
def p(s):return '<p>'+s+'</p>'
def h(s):return '<h3>'+s+'</h3>'
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(s):return '<aside class="callout">'+p(s)+'</aside>'
def state(f,r=.125,q=0.09711541605262927,b=.5):
    y=(r*b+f*f/2)/(r+f);e=(r+f)*q*q/(hypot(q,y)+y);I=r*(1.5*q*q+1/3)+f*(1.25*q*q+f*f/3)
    return y,atan2(q,y)*180/pi,e,I,sqrt(2*I*e),sqrt(2*e/I)

def plot(title,fn,unit,color='water',xmax=1,xlabel='Water remaining (%)'):
    d=Drawing(title,440,290);xs=[xmax*i/500 for i in range(501)];ys=[fn(x) for x in xs];ymax=max(ys)*1.13 or 1
    X=lambda x:55+350*x/xmax;Y=lambda y:235-185*y/ymax
    for j in range(5):
        x=xmax*j/4;y=ymax*j/4;d.line(X(x),50,X(x),235,'grid');d.line(55,Y(y),405,Y(y),'grid');d.text(X(x),255,f'{100*x:.0f}' if xmax==1 else f'{x:.0f}',size=11,anchor='middle');d.text(48,Y(y)+4,f'{y:.3g}',size=11,anchor='end')
    d.path([(X(x),Y(y)) for x,y in zip(xs,ys)],color)
    idx=max(range(len(ys)),key=ys.__getitem__);d.dot(X(xs[idx]),Y(ys[idx]),color,4)
    d.text(55,22,unit,'shell',13);d.text(230,282,xlabel,size=12,anchor='middle')
    return d.finish()

def plots():
    H=.30;mf=.8;g=9.81;pheight=.25
    fields=[('Greatest tilt',lambda f:state(f)[1],'degrees','water','Maximum at 25.0% full.'),('Greatest lifting-energy barrier',lambda f:state(f)[2]*mf*g*H,'joules','cg','Maximum at 100% full.'),('Largest impulse at a fixed 25 cm height',lambda f:state(f)[4]*mf*H*sqrt(g*H)/pheight,'N s','plane','Maximum at 100% full, within the ideal pivot model.'),('Largest initial angular speed required',lambda f:state(f)[5]*sqrt(g/H),'rad/s','green','Maximum near 30.7% full; this is a different imposed initial condition.')]
    return figure('One bottle, four different resistance measures',[(t,plot(t,fn,u,c),desc) for t,fn,u,c,desc in fields], 'Computed immobilized-water model, H = 30 cm, R ≈ 2.913 cm, empty shell = 100 g, full water = 800 g. Uniform thin sidewall with massless end caps determines inertia. Each panel has its own physical units and scale. This is not a prediction of impulsive free-liquid motion. Fill maxima are calculated, not measured.', 'Computed thresholds / explicit rigid-payload model')

def pivot_picture(angle,fill=.25):
    q=0.09711541605262927;y=state(fill)[0];d=Drawing('CG projection relative to a rim pivot at a prescribed tilt',340,320);t=angle*pi/180
    T=lambda x,s:(120+210*((x-q)*cos(t)+s*sin(t)),258-210*((q-x)*sin(t)+s*cos(t)))
    d.path([T(-q,0),T(q,0),T(q,fill),T(-q,fill)],'water','#124966',1,True)
    d.path([T(-q,0),T(q,0),T(q,1),T(-q,1)],'shell','none',2,True)
    X,Y=T(0,y);d.line(20,258,320,258,'muted');d.line(120,35,120,266,'plane','4 5');d.dot(120,258,'plane',4);d.dot(X,Y,'cg',5);d.arrow(X,Y+10,X,Y+55,'cg');d.line(120,245,X,245,'green' if X<120 else 'plane',width=3)
    d.text(18,290,f'{angle:.2f}°; CG '+('inside' if X<119.9 else 'outside' if X>120.1 else 'above pivot'),'shell',14)
    return d.finish()

def pivot_figure():
    return figure('The weight’s line of action changes sides',[(label,pivot_picture(angle),txt) for label,angle,txt in [('Before the crest',15,'Weight acts inside the rim and restores the bottle.'),('At the crest',state(.25)[1],'Weight passes through the pivot: zero gravitational torque.'),('Beyond the crest',35,'Weight acts beyond the rim and drives further tipping.')]],'Computed geometry for a quarter-full immobilized payload. The rim pivot is fixed and does not slip. Amber arrow = weight; its horizontal distance from the pink pivot line is the gravitational moment arm. Rotation is prescribed, not a simulated time trajectory.')

def energy_figure():
    d=Drawing('Potential-energy barriers for empty, quarter-full and full rigid bottles',650,340);H=.3;mf=.8;g=9.81;q=0.09711541605262927;X=lambda a:60+550*a/50;Y=lambda e:265-205*e/.04
    for i in range(6):d.line(X(10*i),45,X(10*i),265,'grid');d.text(X(10*i),285,str(10*i),size=12,anchor='middle')
    for e in [0,.01,.02,.03,.04]:d.line(60,Y(e),610,Y(e),'grid');d.text(50,Y(e)+4,f'{e:.2f}',size=12,anchor='end')
    for f,col,name in [(0,'shell','Empty'),(.25,'water','Quarter-full'),(1,'cg','Full')]:
        y,critical,*_=state(f);fn=lambda a:(.125+f)*mf*g*H*(q*sin(a*pi/180)+y*(cos(a*pi/180)-1))
        d.path([(X(i/10),Y(fn(i/10))) for i in range(min(500,int(20*critical))+1)],col);d.dot(X(critical),Y(fn(critical)),col,4)
    d.text(62,24,'Potential energy above upright (J)','shell',14);d.text(335,311,'Prescribed tilt angle (degrees)',size=13,anchor='middle');d.text(62,335,'White: empty · cyan: quarter-full · amber: full',size=13)
    return figure('A wider angular margin need not mean a higher energy barrier',[('Three potential landscapes',d.finish(),'Quarter-full has the crest farthest to the right. Full has the highest crest.')],'Computed rigid-payload potential relative to its own upright state, with the same reference dimensions as above. Dots mark unstable equilibria. The barrier is a height in energy space, not the visual width of the curve. Each curve stops when it returns to its upright energy or at the plot boundary; later contact and motion are not modeled.')

def force_figure():
    d=Drawing('Forces on an upright bottle just before tipping',440,310);d.rect(155,55,100,200,'shell');d.line(20,256,415,256,'muted');d.dot(255,255,'plane',5)
    d.arrow(205,165,205,225,'cg');d.text(213,208,'m g','cg',15);d.arrow(155,90,275,90,'water');d.text(285,94,'F','water',18);d.arrow(255,255,255,190,'green');d.text(267,207,'N','green',17);d.arrow(255,255,190,255,'plane');d.text(175,275,'friction','plane',13);d.line(120,90,120,255,'water','3 4');d.text(100,177,'p','water',17);d.line(205,288,255,288,'cg');d.text(225,306,'R','cg',15)
    a=Drawing('Sliding versus tipping threshold in push height and friction',440,310);X=lambda v:55+340*v;Y=lambda v:255-205*v;q=0.09711541605262927
    for u in [0,.25,.5,.75,1]:a.line(X(u),45,X(u),255,'grid');a.line(55,Y(u),395,Y(u),'grid');a.text(X(u),275,f'{u:.2f}',size=11,anchor='middle');a.text(48,Y(u)+4,f'{u:.2f}',size=11,anchor='end')
    a.path([(X(l),Y(q/l)) for l in [q+i*(1-q)/250 for i in range(251)]],'cg');a.text(183,75,'Tipping starts first','cg',14);a.text(95,231,'Sliding starts first','water',14);a.text(55,25,'Static friction coefficient μ','shell',13);a.text(225,303,'Push height / bottle height',size=13,anchor='middle')
    return figure('A fixed-height push measures a different resistance', [('Moment balance about the pink rim',d.finish(),'Lever arms are p for the horizontal push and R for the weight. Force arrows are schematic; magnitudes are not to scale.'),('Which instability starts first?',a.finish(),'Boundary: μ = R/p. Increasing mass raises both thresholds but does not move this boundary.')], 'Force diagram: upright bottle on a level dry plane, horizontal push, Coulomb friction, no adhesive force or external hold-down. Phase plot uses R/H = 0.09711541605262927. A threshold predicts onset, not the subsequent slide or fall. At equality the ideal model permits simultaneous onset.')

def inertia_figure():
    panels=[]
    for sep in [35,70]:
        d=Drawing('Equal mass and CG, different rotational inertia',320,220);d.line(25,112,295,112,'grid');d.line(160,45,160,180,'muted','3 4');d.line(160-sep,112,160+sep,112,'shell');d.dot(160-sep,112,'water',12);d.dot(160+sep,112,'water',12);d.dot(160,112,'cg',5);d.text(28,198,'Two equal point masses; same total mass',size=12)
        panels.append(('Separation '+('a' if sep==35 else '2a'),d.finish(),'I = m a²' if sep==35 else 'I = 4 m a²'))
    return figure('A centroid cannot determine rotational inertia',panels,'Exact two-point-mass thought experiment about the dashed axis through the common CG, perpendicular to the connecting rod; the rod is massless. Here m is the total mass of both points. Doubling each point’s distance from the axis quadruples inertia without moving the CG. This is a mass-distribution schematic, not two bottle designs.')

def build():
    questions='<div class="reading"><h2>What can this bottle teach us next?</h2>'+p('The settled upright CG problem is well developed. More learning now comes from changing the observable, the disturbance, or the system boundary. Small corrections improve a number; these six questions can introduce a new physical principle.')
    questions+=table(['New question','New physics','A precise next experiment or model'],[
    ('Does the lowest CG make a bottle hardest to topple?','Stability depends on the disturbance and the quantity being maximized.','Compare critical tilt, a fixed-height push, lifting energy, and an impulse. <a href="#stability">Open the stability lab.</a>'),
    ('Can bottles with identical mass and CG behave differently?','Rotational inertia and internal liquid motion contain information the CG omits.','Redistribute equal masses symmetrically about a fixed CG; compare angular response.'),
    ('What does a scale measure while someone drinks through a straw?','Support forces, acceleration, momentum transport, and mouth/straw contact forces.','Specify all forces and mass fluxes before comparing scale force with remaining weight.'),
    ('Where does the missing mass go in a conservation argument?','An open subsystem and a closed enlarged system obey different bookkeeping.','Draw boundaries around bottle, bottle plus transferred water, and bottle–drinker–Earth.'),
    ('Can the interior be inferred from its CG curve?','Inverse problems: identifiability differs from numerical stability.','Reconstruct the mass–depth relation from an accurate CG curve and test noise amplification.'),
    ('What happens if the bottle floats?','Displaced-fluid geometry, center of buoyancy, and changing restoring torque.','Specify sealed versus open, floating orientation, displaced volume, and internal free surfaces before calculating stability.')])
    questions+=h('Three questions deserve especially deep treatment')+p('These were singled out because each changes the reasoning framework rather than merely adding a small correction. They expose an everyday misconception, connect to a wider theory, and suggest a falsifiable experiment.')
    questions+=h('A. Stability: the objective comes before the optimum')+p('“Hardest to knock over” is incomplete until we specify what is imposed: angle, force, work, impulse, or angular velocity. These have different units and different dependencies on mass and inertia. This question is especially valuable because it challenges the tempting inference that the lowest CG is automatically the most stable state. The next tab develops it in detail.')+energy_figure()
    questions+=h('B. Inverse geometry: can a CG curve reveal the vessel?')+p('Let h be settled water depth, z(h) the combined CG height, M the known empty-bottle mass, and L(h) the total remaining mass. Assume uniform density, a fixed upright interior, fixed shell CG, and no retained films. A prime denotes a derivative with respect to h. The forward balance identity can be inverted:')+eq(r'z\,L=Mb+\int_0^h s\,dL(s),\qquad Lz^{\prime}+zL^{\prime}=hL^{\prime},\qquad \frac{d\ln L}{dh}=\frac{z^{\prime}}{h-z}.')+eq(r'L(h)=M\exp\!\left[\int_0^h\frac{z^{\prime}(s)}{s-z(s)}\,ds\right],\qquad A(h)=\frac{L^{\prime}(h)}{\rho}.')+p('Here b is the empty-shell CG, ρ the water density, and A(h) the horizontal interior area. This turns geometry → CG into CG → geometry. It identifies area versus height, not a unique three-dimensional interior: differently shaped horizontal sections can have the same area and the same CG curve. It is especially valuable because it separates uniqueness with perfect data from reliable inference with noisy data. The measured horizontal coordinate must be depth, not an unknown volume fraction. At h=z, both numerator and denominator vanish; with a smooth positive area, their continuous ratio tends to z″ at the turning point because z′=0 there. A single CG measurement cannot replace the full curve or these assumptions.')+note('Why noise matters: the reconstruction differentiates measured data, divides quantities that can both be small, and then exponentiates an integral. Fit a physically constrained smooth forward model to data and quantify uncertainty rather than directly differentiating raw samples.')
    questions+=h('C. Conservation: the boundary is part of the physics')+p('The bottle’s CG can rise while no remaining material moves upward: low material has left the chosen system. Include the transferred water and drinker, and it is a different system. Include the Earth when discussing support and gravity exchanges. A bottle alone is open during drinking and experiences external forces; an enlarged isolated system is the appropriate setting for a closed-system momentum statement.')+table(['Boundary','What crosses it?','What must be tracked?'],[('Bottle plus remaining water','Mass exits; air can enter; forces act through the straw, hand, and support.','Mass flux, momentum flux, weight, pressure/contact forces, and internal redistribution.'),('Bottle plus all transferred water','Water stays in the accounting, but forces can still be external.','The positions and velocities of transferred water as well as that still in the bottle.'),('Bottle–drinker–Earth, idealized as isolated','No relevant external exchange under the stated idealization.','Total momentum and the full center of mass, including the Earth’s response.')])+p('This is especially valuable because it resolves an apparent paradox and connects the bottle to variable-mass mechanics. “There is a mass flow” does not justify importing a rocket equation without checking the flux velocity, pressure forces, and boundary definition.')+inertia_figure()+'</div>'

    s='<div class="reading"><h2>Which fill makes the bottle hardest to knock over?</h2>'+p('There is no universal best fill. For our running example with immobilized water, quarter-full maximizes critical tilt, full maximizes the lifting-energy barrier and the ideal impulse threshold at a fixed strike height, and about 30.7% full maximizes the required initial angular speed. Freely settling water shifts the critical-tilt optimum to about 25.7% full. These statements answer different experiments.')+note('Read the model label on every visual. “Immobilized water” means a hypothetical rigid payload with the upright water distribution—such as a matched solid replica. It is not ordinary water remaining horizontal while the bottle rotates. “Settled water” means a sealed rigid cylindrical interior, fixed water volume, negligible air mass and capillarity, with enough time to equilibrate at every imposed angle. Neither model solves sloshing impacts.')
    s+=h('1. Define the experiment and the symbols first')+table(['Symbol','Meaning / units'],[('H, R','Internal height and circular support radius; meters. The reference has H = 0.30 m. Uniform water density 1000 kg/m³ and an 800 mL capacity fix R ≈ 0.0291346 m.'),('m₀, M, f','Full water mass, empty-shell mass, and fraction of water remaining. Reference m₀ = 0.80 kg, M = 0.10 kg; 0 ≤ f ≤ 1.'),('r, β, y, q','Ratios M/m₀, b/H, z/H, and R/H. b is shell CG height; z is the upright combined CG. Reference r = 1/8, β = 1/2, q ≈ 0.0971154.'),('m, g, θ','Total remaining mass M+m₀f; gravitational acceleration 9.81 m/s²; lean angle away from upright in radians.'),('p, F, μ','Initial push/strike height above the supporting plane; horizontal force; static friction coefficient.'),('I_P, J, L, ω','Mass moment of inertia about the rim pivot; horizontal impulse; angular impulse about the pivot; angular speed. Units kg m², N s, kg m²/s, rad/s.')])+eq(r'm=m_0(r+f),\qquad y(f)=\frac{r\beta+f^2/2}{r+f},\qquad f_{CG}=\sqrt{r^2+2r\beta}-r.')
    s+=p('The base is flat and circular, the initial CG is on its axis, gravity is uniform, and the support is rigid. The tipping calculation uses the lower rim as a fixed, non-slipping pivot. Changing the support radius is a design change; it is not a consequence of drinking. We state separately when an actual frictional contact can sustain the assumed motion.')+plots()
    s+=h('2. Critical tilt: when does gravity stop restoring upright?')+p('For the rigid-payload reference, measure horizontal and vertical CG position from the right rim pivot. Let x be horizontal displacement toward the falling side and Z height above the original support plane. Rotation gives')+eq(r'x(\theta)=-R\cos\theta+z\sin\theta,\qquad Z(\theta)=R\sin\theta+z\cos\theta.')+p('Weight points vertically downward. Its torque about the rim is mgx in the tipping direction. When x is negative, gravity restores upright; when x is positive, it drives tipping. The boundary is')+eq(r'\theta_c=\tan^{-1}(R/z),\qquad \max_f\theta_c\iff\min_f z,\qquad f_{CG}=0.25\ \text{for the reference}.')+pivot_figure()+p('The reference critical angle is 21.23° at quarter-full, versus 10.99° for either full or empty. Equal endpoint angles do not mean equal impact resistance. This is the release angle of a rigid payload on a fixed rim, or the rigid-body toppling boundary on a sufficiently rough inclined base. Sliding and free-liquid redistribution require the separate models below.')
    s+=h('3. Energy: the height of the hill, not its angular location')+p('Define U(θ) as gravitational potential energy and ΔU as the rise from upright to the unstable equilibrium. The rim constraint fixes the path. Since U=mgZ,')+eq(r'U(\theta)-U(0)=mg[R\sin\theta+z(\cos\theta-1)],\qquad \Delta U=mg\left(\sqrt{R^2+z^2}-z\right).')+p('The cancellation-free form is useful for a slender bottle. Let d=√(q²+y²), and E=ΔU/(m₀gH) be dimensionless energy:')+eq(r'E(f)=(r+f)(d-y)=(r+f)\frac{q^2}{d+y},\qquad E^{\prime}(f)=\frac{d-y}{d}(d+y-f).')+p('Unlike critical tilt, this barrier depends explicitly on total mass. For a midpoint-balanced shell, f−2y=r(f−1)/(r+f)≤0, so d+y−f is strictly positive for R>0. Therefore the energy barrier increases throughout 0 ≤ f ≤ 1: full is best. This is an exact statement within this rigid model, not merely a numerical plot.')+energy_figure()+table(['Fill','Upright CG','Critical rigid tilt','Rigid barrier'],[('Empty','15.00 cm','10.99°','0.00275 J'),('25%','7.50 cm','21.23°','0.01607 J'),('50%','9.00 cm','17.94°','0.02255 J'),('Full','15.00 cm','10.99°','0.02475 J')])+p('These are small gravitational energy barriers for a slender bottle. They are not measured energy-transfer efficiencies. A collision can dissipate or redirect much of its energy into translation, vibration, liquid motion, or the table.')
    s+='<details><summary>General shell CG: when can the energy optimum be interior?</summary>'+p('The monotonic result above uses β=1/2. For general β≥0, the positive stationary fill is')+eq(r'f_E=\min\left\{1,\ \beta+\frac{q^2}{2r}+\sqrt{\left(\beta+\frac{q^2}{2r}\right)^2+q^2}\right\}.')+p('For positive r and q, the derivative starts positive and changes sign only at the unclipped positive root; it is the global maximum if inside the allowed interval. A sufficiently low shell CG can produce an interior energy optimum. At the boundary case β=0, it remains well defined, even though the upright CG minimum occurs empty. Do not extend the thin-sidewall inertia formula below to arbitrary β without specifying a new shell mass distribution.')+'</details>'
    s+=h('4. A slow horizontal push: force at a specified height')+p('Apply a horizontal force F at fixed initial height p on a level plane. At incipient tipping, force and weight moments about the rim balance. With a Coulomb static friction coefficient μ, sliding competes with tipping:')+eq(r'F_{tip}=\frac{mgR}{p},\qquad F_{slide}=\mu mg,\qquad F_{first}=mg\min(R/p,\mu).')+p('Tipping begins before sliding only if R/p<μ. At fixed R and p, both thresholds increase with remaining mass, so the full bottle requires the greatest force for the first loss of static equilibrium. The upright CG height drops out of this onset calculation because the weight’s initial lever arm is R. This does not predict how far a continuously pushed, sliding bottle will travel or whether it will later strike an obstacle and fall.')+force_figure()+p('A prescribed horizontal support acceleration is a different test. For an immobilized payload, a horizontal inertial force ma acts at the CG, giving a_tip/g=R/z and a_slide/g=μ. Mass cancels, so the best rigid tipping-acceleration threshold is again the lowest-CG fill. For slowly equilibrating liquid, the free surface tilts perpendicular to effective gravity; the upright-CG formula must be replaced by a corresponding fluid equilibrium calculation. Arbitrary earthquake-like or vibrational inputs require time dynamics.')
    s+=h('5. A short strike: inertia and the input protocol matter')+p('A horizontal impulse J is the time integral of strike force. In an ideal model the bottle rotates immediately about a fixed rim without slip, bounce, dissipation, or internal motion, and the strike is initially at height p. Angular momentum about the pivot gives L=Jp and I_Pω=L. After the impulse, energy conservation determines whether the crest can be crossed:')+eq(r'\frac{(Jp)^2}{2I_P}>\Delta U,\qquad J_{crit}=\frac{\sqrt{2I_P\Delta U}}{p},\qquad L_{crit}=\sqrt{2I_P\Delta U},\qquad \omega_{crit}=\sqrt{\frac{2\Delta U}{I_P}}.')+p('Equality is a separatrix: in the ideal lossless equation the motion approaches the unstable upright-over-pivot state asymptotically; strict excess is needed to pass it. A force threshold cannot replace an impulse threshold without specifying the force’s duration. Nor can a fixed angular velocity be treated as a fixed impulse: inertia enters these criteria in opposite ways.')+inertia_figure()+p('For the plotted reference, model the shell as a uniform thin cylindrical sidewall with massless retaining end caps, and the immobilized water as a solid cylinder. About the horizontal rim pivot, the parallel-axis theorem gives')+eq(r'I_P=M\left(\frac{3R^2}{2}+\frac{H^2}{3}\right)+m_0 f\left(\frac{5R^2}{4}+\frac{(fH)^2}{3}\right).')+p('Both I_P and ΔU increase with f for this midpoint-shell model, so L_crit and J_crit at fixed p are greatest full. At p=25 cm, J_crit is approximately 0.0166 N s empty, 0.0437 N s quarter-full, and 0.1489 N s full. In contrast, maximizing ω_crit selects approximately 30.7% full for this geometry. That optimum depends on the shell’s second moment, not merely its CG.')+note('A real short strike does not guarantee a fixed pivot or a rigidly moving liquid. Contact impulses, possible lift-off, liquid–wall coupling, and later slosh must be solved or measured. A high wall-friction force cannot be assumed to make water instantaneously rigid. The ideal impulse result is a controlled reference, not a calibrated prediction for an ordinary water bottle.')
    s+=p('The angular-speed optimum can be found explicitly as a one-dimensional root. Define dimensionless inertia ι=I_P/(m₀H²) and angular speed Ω=ω√(H/g). With E and d defined above, an interior stationary fill requires the relative growth rates of energy and inertia to agree:')+eq(r'\Omega_{crit}^2=\frac{2E}{\iota},\quad \iota=r(3q^2/2+1/3)+f(5q^2/4+f^2/3),\quad \frac{E^{\prime}}{E}=\frac{d+y-f}{d(r+f)}=\frac{5q^2/4+f^2}{\iota}=\frac{\iota^{\prime}}{\iota}.')+p('Solving this stationarity condition and comparing all roots with both endpoints gives f≈0.3065 for the reference dimensions. The energy is still increasing there; the angular-speed threshold turns downward because inertia is growing faster in relative terms. This is why the maximum is neither the minimum-CG fill nor the maximum-energy fill.')
    s+=h('6. Let the water settle: the free surface changes the problem')+p('A slowly tilted bottle contains water that remains horizontal in the laboratory. Use a sealed cylinder so volume is fixed and no water spills. Let s be axial distance from the internal bottom, x a horizontal coordinate across its circular section before rotation, and ℓ the laboratory free-surface height above the rim pivot. The water occupies')+eq(r'\Omega_w(\theta)=\{(x,y_{\perp},s):x^2+y_{\perp}^2\le R^2,\ 0\le s\le H,\ (R-x)\sin\theta+s\cos\theta\le\ell\}.')+p('The transverse coordinate y_perp is distinct from the dimensionless upright CG y used above. Choose ℓ by the volume constraint ∫Ωw dV=fπR²H. The liquid CG and its potential energy follow from first moments over this occupied three-dimensional region. The live lab integrates exact circular-segment areas in axial slices and solves the surface height numerically; it does not use the area centroid of a rectangular drawing.')
    s+='</div>'+explorer()+'<div class="reading">'
    s+=h('An exact formula before the surface reaches an end cap')+p('When the free surface intersects every axial line inside the cylinder, local liquid depth is s_top(x)=fH+x tanθ. This requires R|tanθ|≤H min(f,1−f). Circular symmetry gives the area mean of x² as R²/4. Integrating depth and its first moment yields')+eq(r'\int_{\Omega_w}x\,dV=\frac{\pi R^4}{4}\tan\theta,\qquad \int_{\Omega_w}s\,dV=\frac{\pi R^2 f^2H^2}{2}+\frac{\pi R^4}{8}\tan^2\theta.')+p('Define V=U/(m₀gH), the dimensionless absolute potential, and B=rβ+f²/2. For midpoint β=1/2 in the numerical lab, and for any fixed β in this analytic formula:')+eq(r'V_{rigid}=q(r+f)\sin\theta+B\cos\theta,\qquad V_{settled}=V_{rigid}-\frac{q^2\sin^2\theta}{8\cos\theta}.')+p('The negative term is the free-surface energy reduction. At a given angle, liquid can lower its gravitational energy by redistributing; the frozen distribution is only one allowed competitor. More generally, minimization over liquid configurations proves the settled potential cannot exceed the frozen potential at the same angle. Since their upright energies agree, the settled barrier cannot exceed the rigid barrier over the same angle interval. This is a variational argument, not a claim that every dissipative transient follows the minimum instantaneously.')+eq(r'V_{settled}(\theta)=B+q(r+f)\theta-\frac12\left(B+\frac{q^2}{4}\right)\theta^2+O(\theta^3).')+p('The extra negative curvature is the local free-surface destabilization. The same mechanism explains why a moving liquid can undermine the stability of a container even when its upright CG looks favorable. At exactly full or exactly empty, there is no partially filled free surface; the unclipped formula has no nonzero-angle range of validity and must not be extrapolated there.')
    s+=h('Two deductions from the variational view')+p('First, the greatest settled-water energy barrier is also attained full for this midpoint-shell cylinder. At every partial fill its settled barrier is no larger than its rigid barrier; every partial rigid barrier is below the full rigid barrier; and at full there is no free surface, so the settled and rigid results agree. The full-water energy winner therefore survives relaxation, although the critical-angle winner shifts.')+p('Second, the critical angle is unique for the ideal sealed cylinder. For any fixed candidate liquid configuration, potential has the form g(a sinθ+c cosθ), where a and c are nonnegative mass moments about the rim and the positive shell contribution makes the potential strictly concave on 0≤θ≤π/2. Minimizing over admissible liquid configurations preserves concavity. The potential derivative starts positive and ends negative, so there is one crest. This justifies the bracketed critical-angle solve; it does not justify using the same solver for a different contact geometry or spilling vessel.')
    s+='<details><summary>Derive the best settled-water fill in the unclipped regime</summary>'+p('At the critical angle the potential derivative vanishes. Differentiating its zero condition with respect to fill shows that an interior optimum in critical angle must also satisfy f=q cotθ. Substitution gives')+eq(r'\frac{f^2}{2}+rf-r\beta-\frac{q^2}{4}-\frac{q^4}{8f^2}=0,\qquad \theta_{best}=\tan^{-1}(q/f).')+p('For r=1/8, β=1/2, and q≈0.0971154, the root is f=0.256678 and θ=20.7244°. The extreme local depths are 0.21993H and 0.29342H, so the unclipped assumption is self-consistent. The general clipped numerical calculation agrees. This reference optimum is not a geometry-independent rule, and the condition is local unless the other admissible fill regimes are checked; our numerical sweep checks them.')+'</details>'
    s+=table(['At the reference fill','Immobilized water','Freely settling sealed water'],[('25% full: critical tilt','21.2292°','20.7200°'),('25% full: gravitational barrier','0.01607 J','0.01569 J'),('Fill giving greatest critical tilt','25.0000%','25.6678%'),('Greatest critical tilt','21.2292°','20.7244°')])+p('The modest shift here is a calculated result for a slender cylinder, not a universal bound on fluid effects. Wide tanks, necked vessels, internal compartments, slosh, and changing contact can behave much more differently.')
    s+=h('7. Two short animations, rendered with HyperFrames')+p('These silent films use the same computed SVG views and models as the lab. They have ordinary video controls so you can pause and scrub. Motion is explanatory: imposed tilt and fill sweeps are not simulated falling trajectories. Text beneath each film states what is—and is not—being calculated.')+movies()
    s+=h('8. What can overturn these conclusions?')+table(['Effect or altered protocol','What changes?','What remains useful?'],[('Water spills from an open mouth','Mass, moment, and energy exchange depend on angle and history.','The fixed-volume formulas apply only until spilling begins.'),('Sloshing during a short strike','Additional degrees of freedom store and exchange kinetic and potential energy.','The rigid-payload result is a baseline; damping can remove energy but phase-dependent coupling can promote or suppress a fall.'),('Rounded or compliant base','The contact location and contact patch evolve.','Recalculate the potential along the actual admissible contact path.'),('Sliding, bouncing, or loss of contact','The fixed-rim angular-momentum and energy model can fail.','Check normal reaction and friction constraints before accepting the single-pivot motion.'),('A heavier base, cap, or handle','CG and inertia change independently of the liquid.','Use measured shell moments; the energy optimum need not stay full.'),('Different strike heights or pulse durations','The same force or impulse creates a different torque and energy partition.','Specify and control the input before comparing fill fractions.'),('Sticky surface or external hold-down','Adhesion and additional reactions change the allowed motions.','The bare Coulomb-friction threshold is no longer sufficient.')])
    s+=h('9. A clean experiment separates the models')+p('Begin with a rigid replica whose masses match the desired upright mass and centroid. Measure support radius and shell inertia if testing impulses. This gives a controlled test of the rigid formulas. Then compare a sealed water-filled vessel, rotating it slowly enough to settle at every angle. Keep the support and angle protocol fixed. An open vessel is a third experiment, because spilling changes the system.')+table(['Test','Control and measure','Compare with'],[('Release angle','Hinged or non-slipping rim fixture; prescribed angle; no continuing push after release.','θ_c; use matched solid replicas first, then settled water.'),('Slow horizontal force','Force gauge at a fixed measured height; record whether sliding or tipping starts first.','mg min(R/p, μ); independently estimate μ under comparable conditions.'),('Work to the crest','Quasistatic torque–angle measurements; integrate applied torque; track contact and losses.','The potential-energy barrier, with losses separately identified.'),('Short strike','Calibrated impulse and contact height; high-speed video of contact and angular speed.','Only compare with the pivot-impulse formula after verifying its kinematic assumptions.'),('Repeat across fill','Several repeats per fill; uncertainty bars, consistent cap and support.','Different optimal fills for different objectives; do not fit one universal “stability score”.')])+note('The best next measurement is the critical release angle versus fill for a sealed vessel, compared with a matched immobilized payload. It isolates the effect of redistribution before introducing impact dynamics. Report computed predictions, imposed input, measured outcomes, and uncertainty separately.')
    s+=h('10. What this teaches beyond the bottle')+p('A state variable such as CG is a useful compression, but it cannot answer every question about a system. Stability needs a disturbance and a constraint; energy barriers need the whole path; impulse response needs inertia and contact; freely moving liquid adds internal degrees of freedom. The general habit is to ask which observable the model is actually sufficient to predict.')+p('Primary foundations: <a href="https://openstax.org/books/university-physics-volume-1/pages/12-1-conditions-for-static-equilibrium" target="_blank" rel="noopener noreferrer">OpenStax on force and torque equilibrium</a>, <a href="https://openstax.org/books/college-physics/pages/9-3-stability" target="_blank" rel="noopener noreferrer">OpenStax on stability</a>, and <a href="https://openstax.org/books/university-physics-volume-1/pages/10-5-calculating-moments-of-inertia" target="_blank" rel="noopener noreferrer">moments of inertia and the parallel-axis theorem</a>. Bottle-specific optima, free-surface derivation, diagrams, and simulations here are original calculations. <a href="https://github.com/az9713/beyond-waterbottle-CG-physics/tree/main/animations/tipping" target="_blank" rel="noopener noreferrer">Animation sources and reproduction notes</a>.')+'</div>'
    return questions,s

